            ['title' => 'Diurnal Fluctuation & Sundowning', 'icon' => '🌓', 'definition' => 'Symptoms unpredictably fluctuate in severity over a 24-hour cycle, typically worsening in evening hours.'],
            ['title' => 'Underlying Physiological Etiology', 'icon' => '🩺', 'definition' => 'Delirium is fundamentally a systemic medical, toxic, or pharmacological failure affecting cerebral metabolism.'],
            ['title' => 'Three Psychomotor Subtypes', 'icon' => '📊', 'definition' => 'Hyperactive (agitated), Hypoactive (lethargic, underdiagnosed), and Mixed activity presentations.']
