            ['term' => 'Sundowning', 'definition' => 'A clinical phenomenon in which neuropsychiatric symptoms, confusion, and agitation intensify during late afternoon and evening hours.'],
            ['term' => 'Hypoactive Delirium', 'definition' => 'A quiet, lethargic presentation of delirium characterized by apathy, psychomotor slowing, and decreased verbal output, frequently mistaken for depression.'],
            ['term' => 'Clouding of Consciousness', 'definition' => 'A state of reduced mental clarity and attentional alertness that prevents coherent cognitive processing.']
