            ['title' => 'Two-Tier Paraphilic Benchmark', 'icon' => '🔞', 'definition' => 'Atypical erotic focus (Criterion A) only becomes a mental disorder when paired with distress or nonconsenting harm (Criterion B).']
        ],
        'important_terms' => [
            ['term' => 'Instrumental Activities of Daily Living (IADLs)', 'definition' => 'The clinical benchmark of independent everyday functioning distinguishing Major from Mild Neurocognitive Disorder.'],
            ['term' => 'Splitting Defense Mechanism', 'definition' => 'A primitive psychological defense characteristic of Borderline Personality Disorder where others are perceived as entirely good or entirely bad.'],
